CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('reader','editor')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_self ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.user_roles(user_id,role) SELECT user_id,'reader' FROM public.admin_users ON CONFLICT DO NOTHING;
INSERT INTO public.user_roles(user_id,role) SELECT u.id,'editor' FROM auth.users u JOIN public.admin_users a ON a.user_id=u.id WHERE lower(u.email) IN ('ivan07.hcj@gmail.com','mohammed.yahiaoui@nhsm.edu.dz') ON CONFLICT DO NOTHING;
CREATE TABLE public.editor_sessions (session_id uuid PRIMARY KEY,user_id uuid NOT NULL,expires_at timestamptz NOT NULL);
GRANT ALL ON public.editor_sessions TO service_role; ALTER TABLE public.editor_sessions ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_read_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('reader','editor')); $$;
CREATE FUNCTION public.is_editor_identity() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT lower(coalesce(auth.jwt()->>'email','')) IN ('ivan07.hcj@gmail.com','mohammed.yahiaoui@nhsm.edu.dz') AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='editor'); $$;
CREATE OR REPLACE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_editor_identity() AND EXISTS(SELECT 1 FROM public.editor_sessions WHERE user_id=auth.uid() AND session_id=nullif(auth.jwt()->>'session_id','')::uuid AND expires_at>now()); $$;
REVOKE ALL ON FUNCTION public.can_read_admin(),public.is_editor_identity(),public.is_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_read_admin(),public.is_editor_identity(),public.is_admin() TO authenticated,service_role;
CREATE POLICY events_reader ON public.events FOR SELECT TO authenticated USING(public.can_read_admin());
CREATE POLICY sponsors_reader ON public.sponsors FOR SELECT TO authenticated USING(public.can_read_admin());
CREATE POLICY links_reader ON public.external_links FOR SELECT TO authenticated USING(public.can_read_admin());
CREATE POLICY event_sponsors_reader ON public.event_sponsors FOR SELECT TO authenticated USING(public.can_read_admin());
CREATE POLICY memberships_reader ON public.membership_requests FOR SELECT TO authenticated USING(public.can_read_admin());
CREATE POLICY registrations_reader ON public.event_registrations FOR SELECT TO authenticated USING(public.can_read_admin());
CREATE TABLE public.club_members(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,club_role text NOT NULL DEFAULT '',photo_url text,sort_order integer NOT NULL DEFAULT 0,is_active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.club_members TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.club_members TO authenticated; GRANT ALL ON public.club_members TO service_role; ALTER TABLE public.club_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY members_public ON public.club_members FOR SELECT TO anon,authenticated USING(is_active); CREATE POLICY members_reader ON public.club_members FOR SELECT TO authenticated USING(public.can_read_admin()); CREATE POLICY members_editor ON public.club_members FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin());
ALTER TABLE public.external_links ADD COLUMN platform text;